function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'SORTracker' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with SORTracker and no arguments.';
  if (operations.length - 1 > 40000) return 'At most 4 * 10^4 calls in total.';
  const names = new Set();
  let adds = 0, gets = 0;
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'add') {
      if (a.length !== 2) return 'add takes a name and a score.';
      const [name, score] = a;
      if (typeof name !== 'string' || !/^[a-z]{1,10}$/.test(name)) return 'Each name has 1 to 10 lowercase letters.';
      if (names.has(name)) return 'Every name must be unique.';
      names.add(name);
      if (!Number.isInteger(score) || score < 1 || score > 100000) return 'Each score is an integer from 1 to 10^5.';
      adds++;
    } else if (operations[i] === 'get') {
      if (a.length !== 0) return 'get takes no arguments.';
      gets++;
      if (gets > adds) return 'get cannot be called more times than add.';
    } else {
      return 'Only add and get can follow the constructor.';
    }
  }
  return null;
}

