class SORTracker {
  constructor() {
    const better = (a, b) => a.score > b.score || (a.score === b.score && a.name < b.name);
    this.top = { items: [], first: (a, b) => better(b, a) };
    this.rest = { items: [], first: better };
  }

  add(name, score) {
    this.push(this.top, { name, score });
    this.push(this.rest, this.pop(this.top));
  }

  get() {
    const location = this.pop(this.rest);
    this.push(this.top, location);
    return location.name;
  }

  push(heap, item) {
    const items = heap.items;
    items.push(item);
    let index = items.length - 1;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (!heap.first(items[index], items[parent])) break;
      [items[index], items[parent]] = [items[parent], items[index]];
      index = parent;
    }
  }

  pop(heap) {
    const items = heap.items;
    const root = items[0];
    const last = items.pop();
    if (items.length === 0) return root;
    items[0] = last;
    let index = 0;
    for (;;) {
      const left = 2 * index + 1;
      const right = left + 1;
      let next = index;
      if (left < items.length && heap.first(items[left], items[next])) next = left;
      if (right < items.length && heap.first(items[right], items[next])) next = right;
      if (next === index) break;
      [items[index], items[next]] = [items[next], items[index]];
      index = next;
    }
    return root;
  }
}

