class SORTracker {
  // Keep every location and sort them all on each query.
  constructor() {
    this.all = [];
    this.calls = 0;
  }

  add(name, score) {
    this.all.push([score, name]);
  }

  get() {
    this.calls++;
    const ranked = this.all.slice().sort((x, y) => (y[0] - x[0]) || (x[1] < y[1] ? -1 : x[1] > y[1] ? 1 : 0));
    return ranked[this.calls - 1][1];
  }
}

