function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const calls = large ? 499 : int(1, 14);
  const letters = large ? 'abcdefghijklmnopqrstuvwxyz' : 'abc';
  const longest = large ? 10 : 3;
  const scoreTop = large ? (rand() < 0.5 ? 20 : 100000) : (rand() < 0.6 ? 2 : 6);
  const addRate = 0.5 + rand() * 0.3;
  const used = new Set();
  const freshName = () => {
    for (;;) {
      let name = '';
      const length = int(1, longest);
      for (let i = 0; i < length; i++) name += letters[int(0, letters.length - 1)];
      if (!used.has(name)) { used.add(name); return name; }
    }
  };
  const operations = ['SORTracker'];
  const args = [[]];
  let adds = 0, gets = 0;
  for (let i = 0; i < calls; i++) {
    // Small inputs have at most 39 possible names; stop adding before they run out.
    const canAdd = large || used.size < 30;
    if (canAdd && (gets === adds || rand() < addRate)) {
      operations.push('add');
      args.push([freshName(), int(1, scoreTop)]);
      adds++;
    } else if (gets < adds) {
      operations.push('get');
      args.push([]);
      gets++;
    }
  }
  return [operations, args];
}
